// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Wallet} from "../src/Wallet.sol";

contract InvMutTest is Test {
    Wallet c;
    function setUp() public { c = new Wallet(); }
    function testRegression_property() public {
        vm.deal(address(this), 10 ether);
        vm.prank(address(this));
        c.deposit{value: 1 ether}();

        address attacker = address(0x1234);
        vm.deal(attacker, 1 ether);
        vm.prank(attacker);
        (bool success, ) = address(c).call(abi.encodeWithSelector(c.migrateTo.selector, attacker));
        assertTrue(success == false && address(c).balance == 1 ether);
    }
}
